  ('mcq-v2-internet-banking-control-1', 'en', 'Who should control the company''s internet banking?', '[{"key":"A","text":"Only the company''s authorised director"},{"key":"B","text":"The accounting firm the company hires"},{"key":"C","text":"The agent who helped open the account"},{"key":"D","text":"Any employee who knows the password"}]'::jsonb, 'A', 'The bank expects the authorised director to control the account personally, never to hand it to someone else.'),
