  ('mcq-v2-otp-control-2', 'en', 'Who should control the company''s OTP?', '[{"key":"A","text":"The company''s authorised director, personally"},{"key":"B","text":"The accounting firm the company hires"},{"key":"C","text":"Whoever helped register the company"},{"key":"D","text":"Anyone who asks for the code"}]'::jsonb, 'A', 'The OTP confirms transactions on the account. The authorised director keeps the phone and receives the code personally, and never passes it on.'),
